try (java.io.InputStream is = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(grid_png));
     java.io.ByteArrayOutputStream os = new java.io.ByteArrayOutputStream()) {

    net.coobird.thumbnailator.Thumbnailator.createThumbnail(is, os, "jpg", 50, 50);

    byte[] resultBytes = os.toByteArray();
    assert resultBytes.length > 0 : "Output stream should contain data";

    try (java.io.InputStream in = new java.io.ByteArrayInputStream(resultBytes)) {
        java.awt.image.BufferedImage resultImage = javax.imageio.ImageIO.read(in);
        assert resultImage != null : "Resulting image should be readable";
        assert resultImage.getWidth() <= 50 && resultImage.getHeight() <= 50 : "Image should be resized to fit within 50x50";
        System.out.println("__CHECK__ createThumbnail " + resultImage.getWidth() + "x" + resultImage.getHeight());
    }
} catch (java.io.IOException e) {
    throw new RuntimeException(e);
}
